select (select jsonb_build_object(
'relations',(select jsonb_agg(obj order by obj->>'nspname' collate "C",obj->>'relname' collate "C") from (select jsonb_build_object('nspname',n.nspname,'relname',c.relname,'relkind',c.relkind,'owner',c.relowner::regrole::text,'rls',c.relrowsecurity,'forced',c.relforcerowsecurity,
'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
'constraints',(select jsonb_agg(jsonb_build_object('name',k.conname,'def',pg_get_constraintdef(k.oid)) order by k.conname collate "C") from pg_constraint k where k.conrelid=c.oid and k.contype<>'n'),
'indexes',(select jsonb_agg(jsonb_build_object('name',ic.relname,'def',pg_get_indexdef(i.indexrelid)) order by ic.relname collate "C") from pg_index i join pg_class ic on ic.oid=i.indexrelid where i.indrelid=c.oid),
'triggers',(select jsonb_agg(jsonb_build_object('name',tg.tgname,'def',pg_get_triggerdef(tg.oid),'function',tg.tgfoid::regprocedure::text,'handler_md5',md5(pg_get_functiondef(tg.tgfoid))) order by tg.tgname collate "C") from pg_trigger tg where tg.tgrelid=c.oid and not tg.tgisinternal),
'policies',(select jsonb_agg(jsonb_build_object('name',p.polname,'cmd',p.polcmd,'roles',(select jsonb_agg(case when x=0 then 'PUBLIC' else x::regrole::text end order by case when x=0 then 'PUBLIC' else x::regrole::text end collate "C") from unnest(p.polroles) x),'permissive',p.polpermissive,'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by p.polname collate "C") from pg_policy p where p.polrelid=c.oid),
'table_acl',(select jsonb_agg(jsonb_build_object('role',case when a.grantee=0 then 'PUBLIC' else a.grantee::regrole::text end,'grantor',a.grantor::regrole::text,'privilege',a.privilege_type,'grantable',a.is_grantable) order by case when a.grantee=0 then 'PUBLIC' else a.grantee::regrole::text end collate "C",a.privilege_type collate "C",a.grantor::regrole::text collate "C") from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a),
'column_acl',(select jsonb_agg(jsonb_build_object('column',at.attname,'role',case when a.grantee=0 then 'PUBLIC' else a.grantee::regrole::text end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by at.attname collate "C",case when a.grantee=0 then 'PUBLIC' else a.grantee::regrole::text end collate "C",a.privilege_type collate "C") from pg_attribute at cross join lateral aclexplode(at.attacl) a where at.attrelid=c.oid and at.attnum>0 and not at.attisdropped)
) as obj from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and ((n.nspname='public' and c.relname in ('businesses','campaigns','creatives','ad_accounts','meta_connections','metrics_daily','exclusoes_de_dados','commercial_order_units','clientes','execucoes','criativos','campanhas_meta','metricas_diarias','respostas_do_dono','execucoes_de_rotina','perguntas_apresentadas','campanhas_criacao','identidade_visual','narrativa_negocio','pessoas_do_negocio','entrevistas','propostas_de_perfil','itens_da_proposta','divergencias_de_cadastro','profiles','leads_lp','commercial_orders','revops_people','revops_prospect_organizations','revops_opportunities','revops_opportunity_people','revops_source_references','revops_interactions','revops_interaction_opportunities','creative_generation_requests','fiscal_documents','onboarding_meetings','manager_accounts','commercial_payment_events','fiscal_obligations','commercial_manual_evidence','historical_contract_access','historical_contract_access_events','commercial_events','commercial_payment_email_outbox','checkout_3ds_context','checkout_security_attempts')) or(n.nspname='vault' and c.relname='secrets') or(n.nspname='auth' and c.relname='users'))) rels),
'functions',(select jsonb_agg(obj order by obj->>'schema' collate "C",obj->>'name' collate "C",obj->>'identity' collate "C") from (select jsonb_build_object('schema',n.nspname,'name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'return_type',p.prorettype::regtype::text,'language',l.lanname,'definer',p.prosecdef,'volatility',p.provolatile,'strict',p.proisstrict,'parallel',p.proparallel,'leakproof',p.proleakproof,'retset',p.proretset,'kind',p.prokind,'config',p.proconfig,'body_md5',md5(p.prosrc),'owner',p.proowner::regrole::text,'acl',(select jsonb_agg(jsonb_build_object('role',case when a.grantee=0 then 'PUBLIC' else a.grantee::regrole::text end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by case when a.grantee=0 then 'PUBLIC' else a.grantee::regrole::text end collate "C",a.privilege_type collate "C") from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)) as obj from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in ('public','private','auth') and p.proname in ('marcar_conexao_meta_quebrada','desautorizar_meta','apagar_dados_da_meta','status_da_exclusao','owns_business','registrar_procedencia','procedencia_do_campo','set_atualizado_em','aplicar_proposta','escrever_apenas_se_livre','revops_register_interest','revops_register_interaction','documento_contratante_valido','conferir_documento_contratante_gravado','registrar_evidencia_manual','revisar_evidencia_manual','emitir_acesso_contratado','aceitar_acesso_contratado','revogar_acesso_contratado','handle_new_user','registrar_pedido_pix_assistido','registrar_pedido_self_service','registrar_pedido_pix_assistido_com_lead','registrar_pedido_asaas_assistido','set_updated_at','uid','registrar_evento_financeiro_asaas','registrar_evento_financeiro_comercial','registrar_evento_inicial_3ds','registrar_evento_inicial_3ds_comercial','reservar_assinatura_apos_3ds','aprovar_pagamento_api_comercial','aprovar_pagamento_api_self_service','pedido_asaas_comercial_elegivel','consumir_limite_checkout','evento_asaas_impede_confirmacao','checkout_producao_schema_v1')) funcs),
'u3_function_details',(select coalesce(jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_arguments(p.oid),'variadic',p.provariadic::text,'support',p.prosupport::text) order by p.proname collate "C"),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('aplicar_proposta','escrever_apenas_se_livre','revops_register_interest','revops_register_interaction','documento_contratante_valido','conferir_documento_contratante_gravado','registrar_evidencia_manual','revisar_evidencia_manual','emitir_acesso_contratado','aceitar_acesso_contratado','revogar_acesso_contratado','handle_new_user','registrar_pedido_pix_assistido','registrar_pedido_self_service','registrar_pedido_pix_assistido_com_lead','registrar_pedido_asaas_assistido','set_updated_at','uid','registrar_evento_financeiro_asaas','registrar_evento_financeiro_comercial','registrar_evento_inicial_3ds','registrar_evento_inicial_3ds_comercial','reservar_assinatura_apos_3ds','aprovar_pagamento_api_comercial','aprovar_pagamento_api_self_service','pedido_asaas_comercial_elegivel','consumir_limite_checkout','evento_asaas_impede_confirmacao','checkout_producao_schema_v1')),
'defaults',(select jsonb_agg(to_jsonb(d) order by d.oid) from pg_default_acl d),
'ledger',(select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version collate "C",name collate "C") from supabase_migrations.schema_migrations),
'incoming_fks',(select jsonb_agg(jsonb_build_object('source',k.conrelid::regclass::text,'target',k.confrelid::regclass::text,'name',k.conname,'def',pg_get_constraintdef(k.oid)) order by k.conrelid::regclass::text collate "C",k.conname collate "C") from pg_constraint k where k.contype='f' and k.confrelid in ('public.meta_connections'::regclass,'public.ad_accounts'::regclass,'public.metrics_daily'::regclass)),
'vault_access',jsonb_build_object('usage',has_schema_privilege('postgres','vault','USAGE'),'select',has_table_privilege('postgres','vault.secrets','SELECT'),'delete',has_table_privilege('postgres','vault.secrets','DELETE'))
))||jsonb_build_object('column_details',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'column',a.attname,'identity',a.attidentity,'generated',a.attgenerated,'comment',col_description(c.oid,a.attnum)) order by n.nspname collate "C",c.relname collate "C",a.attnum) from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid where n.nspname in('public','auth') and c.relname in('commercial_orders','onboarding_meetings','fiscal_documents','commercial_manual_evidence','fiscal_obligations','historical_contract_access','historical_contract_access_events','users','commercial_events') and a.attnum>0 and not a.attisdropped),'auth_read_capability',jsonb_build_object('schema',has_schema_privilege('postgres','auth','USAGE'),'select',has_table_privilege('postgres','auth.users','SELECT')),'sequences',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'owner',c.relowner::regrole::text,'type',format_type(z.seqtypid,null),'start',z.seqstart::text,'increment',z.seqincrement::text,'min',z.seqmin::text,'max',z.seqmax::text,'cache',z.seqcache::text,'cycle',z.seqcycle,'acl',c.relacl::text) order by n.nspname collate "C",c.relname collate "C"),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_sequence z on z.seqrelid=c.oid where n.nspname='public' and c.relname='historical_contract_access_events_id_seq'))||jsonb_build_object('extra_column_details',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'column',a.attname,'identity',a.attidentity,'generated',a.attgenerated,'comment',col_description(c.oid,a.attnum)) order by n.nspname collate "C",c.relname collate "C",a.attnum) from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid where n.nspname='public' and c.relname in('commercial_payment_email_outbox','checkout_3ds_context','checkout_security_attempts') and a.attnum>0 and not a.attisdropped))||jsonb_build_object('function_comments',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'comment',obj_description(p.oid,'pg_proc')) order by n.nspname collate "C",p.proname collate "C"),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('evento_asaas_impede_confirmacao','checkout_producao_schema_v1')));
